package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Cancels the person's last statement: only a steward may, and a person with no statement is refused. The claims it
 * bound are unbound (live again); a figure an earlier statement bound is not restored.
 */
public class CancelStatement {
    public void cancel(@Val Person person, @Val StatementTaker taker, RoleRepository roles, StatementRepository statements,
            ClaimRepository claims, Out<Statement> cancelled) throws InvalidPersonException {
        String sheetId = person.sheetId();
        if (!RoleRepository.STEWARD.equals(roles.roleOf(sheetId, taker.by()))) {
            throw new InvalidPersonException("Only a steward may cancel a statement");
        }
        Statement last = statements.last(sheetId, person.id());
        if (last == null || !statements.removeLast(sheetId, person.id())) {
            throw new InvalidPersonException(person.name() + " has no statement");
        }
        claims.unbindAll(sheetId, person.id());
        cancelled.set(new Statement(sheetId, person.id(), last.takenOn(), last.dueTotal(), last.claims(), taker.by(), last.asOf(), last.madeOn()));
    }
}
# POST /api/sheets/{sheetId}/people/{personId}/statements — take the person's statement on the sheet's
# today: records their due-total and binds each of their claims that counts to its due as shown now, late charge included
# (one that does not count is unbound). A person not on the sheet is a 404 and writes nothing.
# With asOf (yyyy-MM-dd) it is taken as of that date, the sheet as it stood at its end (see TakeStatement); a
# date after the sheet's today, or before the person was added, is a 400 and writes nothing.
# Responds 201 with the statement.
validate:
  class: net.officefloor.hq.app.statement.ValidateStatement
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: take
take:
  class: net.officefloor.hq.app.statement.TakeStatement
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.statement.RecordStatementTaken
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.statement.RespondWithStatementCreated

